package defaultcontent

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/luckylhb90/bnbloc/component"
	"github.com/luckylhb90/bnbloc/core"
)

// The Expert builder: its always-on INSTRUCTIONS.md, and its on-demand
// format skill (the package format and an example package per kind in
// references/examples.md). The save's limits are not copied: the skill
// points at the file every room's records hold, generated by the platform
// from its validator (component.RoomContentLimitsFile).
const (
	builderName     = "expert-builder"
	formatSkill     = "package-format"
	formatSkillFile = "skills/" + formatSkill + "/SKILL.md"
	examplesFile    = "skills/" + formatSkill + "/references/examples.md"
	// maxAlwaysOnTokens bounds the builder's INSTRUCTIONS.md, re-sent with
	// every request of a builder session (tokens as chars/4).
	maxAlwaysOnTokens = 1500
)

func TestBuilderInstructionsAndFormat(t *testing.T) {
	b := get(t, builderName)
	if b.Manifest.Kind != kindExpert {
		t.Fatalf("the builder is a %s", b.Manifest.Kind)
	}
	says(t, "the builder's instructions", b.file(t, "INSTRUCTIONS.md"), "save_component", "get_component", "try_draft", "publish_component", "drafts/<name>/", "Save as prompt pack", "starter", "`"+formatSkill+"`", "person's language")
	says(t, "the format skill", b.file(t, formatSkillFile), kindExpert, kindSkill, kindPrompt, kindAssist, "requires.prompts", "`mcp`", "`team`", "mcp.stdio", "mcp.http:", `"scripts"`, "`starter: true`", "`ref`", "`everyRoom: true`")
}

// The builder's always-on part stays small: the format lives in the
// on-demand skill.
func TestBuilderAlwaysOnBudget(t *testing.T) {
	if tokens := len(get(t, builderName).file(t, "INSTRUCTIONS.md")) / 4; tokens > maxAlwaysOnTokens {
		t.Fatalf("the builder's INSTRUCTIONS.md is about %d tokens, the budget is %d: move what is needed only while drafting into the %s skill", tokens, maxAlwaysOnTokens, formatSkill)
	}
}

// The format skill's reference carries example packages; they validate
// with the platform's validator, or the builder teaches agents a format
// that fails on save.
func TestBuilderExamplesValidate(t *testing.T) {
	re := regexp.MustCompile("(?s)<!-- example: (\\S+) -->\\s*```[a-z]*\\n(.*?)\\n```")
	root := t.TempDir()
	names := map[string]bool{}
	for _, m := range re.FindAllStringSubmatch(get(t, builderName).file(t, examplesFile), -1) {
		parts := strings.SplitN(m[1], "/", 3) // drafts/<name>/<file>
		if len(parts) != 3 || parts[0] != "drafts" {
			t.Fatalf("example path %q is not drafts/<name>/<file>", m[1])
		}
		path := filepath.Join(root, parts[1], filepath.FromSlash(parts[2]))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(m[2]+"\n"), 0o644); err != nil {
			t.Fatal(err)
		}
		names[parts[1]] = true
	}
	var dirs []string
	for n := range names {
		dirs = append(dirs, filepath.Join(root, n))
	}
	kinds := map[string]bool{}
	for _, r := range check(t, dirs...) {
		if r.Error != "" {
			t.Fatalf("example %s does not validate: %s", filepath.Base(r.Dir), r.Error)
		}
		if r.Name != filepath.Base(r.Dir) {
			t.Fatalf("example %s names %q", filepath.Base(r.Dir), r.Name)
		}
		kinds[r.Kind] = true
	}
	team := false
	for n := range names {
		raw, _ := os.ReadFile(filepath.Join(root, n, "component.json"))
		s := string(raw)
		team = team || strings.Contains(s, `"team"`) && strings.Contains(s, `"prompts"`) && strings.Contains(s, `"mcp"`)
	}
	if !kinds[kindExpert] || !kinds[kindSkill] || !kinds[kindPrompt] || !team {
		t.Fatalf("example kinds = %v, team expert with prompt packs and an MCP tool = %v", kinds, team)
	}
}

// statedLimitRE finds a limit stated in prose ("at most 120", "8000
// characters", "64 KiB").
var statedLimitRE = regexp.MustCompile(`(?i)\b(at most|up to|no more than|maximum( of)?|limit(ed)? (of|to))\s+\d|\b\d[\d,.]*\s*(characters|chars|bytes|KiB|MiB|KB|MB|files|entries|items|tags|skills|prompts|variables|options|roles|members)\b`)

var fenceRE = regexp.MustCompile("(?s)```.*?```")

// The builder states no limit: the save's limits are the platform's file
// in the room's records, which the format skill names, so nothing here
// can disagree with the validator.
func TestBuilderStatesNoLimit(t *testing.T) {
	b := get(t, builderName)
	limits := strings.TrimPrefix(component.RoomContentLimitsFile, core.RoomContextDir)
	if !strings.Contains(b.file(t, formatSkillFile), "`"+limits+"`") {
		t.Errorf("the %s skill does not point at the room records' %s", formatSkill, limits)
	}
	for _, name := range []string{"INSTRUCTIONS.md", formatSkillFile, examplesFile, "component.json"} {
		for _, m := range statedLimitRE.FindAllString(fenceRE.ReplaceAllString(b.file(t, name), ""), -1) {
			t.Errorf("%s states a limit: %q (the save's limits are the platform's %s)", name, m, limits)
		}
	}
}

// The workshop (the platform's web) opens with the builder's quick
// prompts: per kind it drafts the one titled "Create … <kind>", and for an
// existing component the one titled "Improve …", whose first blank names
// it.
func TestBuilderQuickPromptsServeTheWorkshop(t *testing.T) {
	qps := get(t, builderName).Manifest.QuickPrompts
	for _, kind := range []string{"expert", "skill", "prompt", "assist"} { // the kinds the workshop drafts
		n := 0
		for _, q := range qps {
			title := strings.ToLower(q.Title)
			if strings.HasPrefix(title, "create") && strings.Contains(title, kind) {
				n++
			}
		}
		if n != 1 {
			t.Errorf("%d quick prompts titled \"Create … %s\", want 1", n, kind)
		}
	}
	n := 0
	for _, q := range qps {
		if strings.HasPrefix(strings.ToLower(q.Title), "improve") {
			n++
			if !strings.Contains(q.Prompt, "___") {
				t.Errorf("the improve quick prompt %q has no ___ blank for the component", q.Prompt)
			}
		}
	}
	if n != 1 {
		t.Errorf("%d quick prompts titled \"Improve …\", want 1", n)
	}
}
